package resourceadmission

import (
	"errors"
	"io"
	"io/fs"
	"os"
	"strings"
	"testing"
	"testing/fstest"

	"github.com/hishamkaram/delegation-layer/internal/task"
)

var (
	errReadFault  = errors.New("read fault")
	errCloseFault = errors.New("close fault")
)

// probeFS serves one file of generated bytes and records what was consumed
// and whether it was closed.
type probeFS struct {
	size      int
	readErr   error
	closeErr  error
	openErr   error
	consumed  int
	closed    int
	openCalls int
}

type probeFile struct{ fs *probeFS }

func (p *probeFS) Open(string) (fs.File, error) {
	p.openCalls++
	if p.openErr != nil {
		return nil, p.openErr
	}
	return probeFile{p}, nil
}

func (f probeFile) Read(b []byte) (int, error) {
	if f.fs.readErr != nil {
		return 0, f.fs.readErr
	}
	n := min(len(b), f.fs.size-f.fs.consumed)
	if n == 0 {
		return 0, io.EOF
	}
	for i := range b[:n] {
		b[i] = 'a'
	}
	f.fs.consumed += n
	return n, nil
}

func (f probeFile) Close() error {
	f.fs.closed++
	return f.fs.closeErr
}

func (f probeFile) Stat() (fs.FileInfo, error) { return nil, errors.New("not used") }

func TestReadTextAcceptsExactlyTheLimit(t *testing.T) {
	probe := &probeFS{size: maxMetadataBytes}
	text, present, err := readText(probe, "f")
	if err != nil || !present || len(text) != maxMetadataBytes {
		t.Fatalf("len %d present %v err %v, want the full file", len(text), present, err)
	}
	if probe.closed != 1 {
		t.Fatalf("closed %d times, want 1", probe.closed)
	}
}

func TestReadTextOneByteOverTheLimitIsAnErrorWithBoundedConsumption(t *testing.T) {
	probe := &probeFS{size: 1 << 30}
	text, present, err := readText(probe, "f")
	if !errors.Is(err, task.ErrControlRecordTooBig) || text != "" || !present {
		t.Fatalf("text len %d present %v err %v, want an overflow error and no partial text", len(text), present, err)
	}
	if probe.consumed > maxMetadataBytes+1 {
		t.Fatalf("consumed %d bytes, want at most %d", probe.consumed, maxMetadataBytes+1)
	}
	if probe.closed != 1 {
		t.Fatalf("closed %d times, want 1 on the overflow path", probe.closed)
	}
}

func TestReadTextKeepsReadAndCloseFaultsAndClosesEveryPath(t *testing.T) {
	cases := []struct {
		name  string
		probe *probeFS
		want  []error
	}{
		{"read fault", &probeFS{size: 10, readErr: errReadFault}, []error{errReadFault}},
		{"close fault", &probeFS{size: 10, closeErr: errCloseFault}, []error{errCloseFault}},
		{"both", &probeFS{size: 10, readErr: errReadFault, closeErr: errCloseFault}, []error{errReadFault, errCloseFault}},
		{"overflow and close fault", &probeFS{size: 1 << 30, closeErr: errCloseFault}, []error{task.ErrControlRecordTooBig, errCloseFault}},
	}
	for _, tc := range cases {
		text, present, err := readText(tc.probe, "f")
		if text != "" || !present || err == nil {
			t.Errorf("%s: text %q present %v err %v, want a retained fault and no text", tc.name, text, present, err)
		}
		for _, want := range tc.want {
			if !errors.Is(err, want) {
				t.Errorf("%s: err = %v, want it to include %v", tc.name, err, want)
			}
		}
		if tc.probe.closed != 1 {
			t.Errorf("%s: closed %d times, want 1", tc.name, tc.probe.closed)
		}
	}
}

func TestReadTextAbsenceIsClassifiedFromOpenOnly(t *testing.T) {
	if _, present, err := readText(&probeFS{openErr: fs.ErrNotExist}, "f"); present || err != nil {
		t.Fatalf("present %v err %v, want a clean absence", present, err)
	}
	if _, present, err := readText(&probeFS{openErr: fs.ErrPermission}, "f"); !errors.Is(err, fs.ErrPermission) || present {
		t.Fatalf("present %v err %v, want the permission error", present, err)
	}
	// A not-exist error surfacing from Read or Close is a fault, never a
	// disabled controller.
	for _, probe := range []*probeFS{{size: 5, readErr: os.ErrNotExist}, {size: 5, closeErr: os.ErrNotExist}} {
		if _, present, err := readText(probe, "f"); err == nil || !present {
			t.Fatalf("present %v err %v, want a fault", present, err)
		}
	}
}

func TestTruncatedMountinfoIsNeverParsed(t *testing.T) {
	// The first line alone would resolve the target; the file is over the
	// limit, so nothing may be parsed.
	tree := hostTree("0::/a/b\n")
	tree[mountinfoFile] = file(stdMountinfo + strings.Repeat("x", maxMetadataBytes))
	got := readerFor(tree).sample(pid4242)
	if got.ok || got.failure() != ReasonUnreadable {
		t.Fatalf("reading = %+v, want unreadable", got)
	}
	if scope := readerFor(tree).membership(*pid4242); scope.ok {
		t.Fatalf("membership = %+v, must not resolve from truncated data", scope)
	}
}

func TestOversizedLevelFileMakesOnlyThatObservationUnknown(t *testing.T) {
	tree := hostTree("0::/a/b\n")
	tree["sys/fs/cgroup/a/memory.stat"] = file(strings.Repeat("x", maxMetadataBytes+1))
	sample := sampleOf(t, readerFor(tree), pid4242)
	if m := sample.levels[1].memory; m.ok || m.failure() != ReasonUnreadable {
		t.Fatalf("memory = %+v, want unreadable", m)
	}
	if !sample.levels[1].cpu.ok || !sample.psiStallUS.ok {
		t.Fatalf("level %+v psi %+v, want the other observations intact", sample.levels[1], sample.psiStallUS)
	}
}

// deepTree has a target nested depth levels below the mount root.
func deepTree(depth int) fstest.MapFS {
	segments := strings.Repeat("/d", depth)
	tree := fstest.MapFS{
		mountinfoFile:      file(stdMountinfo),
		selfCgroupFile:     file("0::" + segments + "\n"),
		"proc/4242/cgroup": file("0::" + segments + "\n"),
	}
	tree["sys/fs/cgroup"+segments+"/memory.pressure"] = file(psiTarget)
	return tree
}

func TestAncestorWalkIsBoundedAndIncompleteCoverageIsReported(t *testing.T) {
	cases := []struct {
		name       string
		depth      int
		wantLevels int
		wantHidden bool
	}{
		{"target plus 127 parents fit", maxObservedAncestors - 1, maxObservedAncestors, false},
		{"one more level is incomplete", maxObservedAncestors, maxObservedAncestors, true},
		{"far deeper stays at the limit", maxObservedAncestors + 400, maxObservedAncestors, true},
	}
	for _, tc := range cases {
		sample := sampleOf(t, readerFor(deepTree(tc.depth)), pid4242)
		if len(sample.levels) != tc.wantLevels || sample.hiddenAncestors != tc.wantHidden {
			t.Errorf("%s: %d levels hidden %v, want %d and %v", tc.name, len(sample.levels), sample.hiddenAncestors, tc.wantLevels, tc.wantHidden)
		}
	}
}
